CREATE TABLE IF NOT EXISTS richo_version_certifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),version text NOT NULL,level text NOT NULL CHECK(level IN('L1','L2','L3','L4','L5')),commit_sha text NOT NULL,status text NOT NULL DEFAULT 'certified',assessment jsonb NOT NULL,notes text,correlation_id text,certified_at timestamptz NOT NULL DEFAULT now(),UNIQUE(version,level,commit_sha));
CREATE TABLE IF NOT EXISTS richo_release_channels(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),version text NOT NULL,level text NOT NULL,channel text NOT NULL CHECK(channel IN('alpha','beta','rc','stable')),artifact_digest text,environment text,status text NOT NULL DEFAULT 'candidate',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_level_capabilities(level text NOT NULL,capability_key text NOT NULL,required boolean NOT NULL DEFAULT true,description text,PRIMARY KEY(level,capability_key));
